<?php require __DIR__.'/bootstrap.php'; $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$message=trim($_POST['message']??'');if(!valid_name($name)||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($message)<10)$errors[]='Enter a valid name, email, and message of at least 10 characters.';if(!$errors){$dir=__DIR__.'/database/data';if(!is_dir($dir))mkdir($dir,0755,true);$record=[$name,$email,$message,date('c')];$fp=fopen($dir.'/contact_messages.csv','ab');flock($fp,LOCK_EX);fputcsv($fp,$record);flock($fp,LOCK_UN);fclose($fp);if($pdo){try{$s=$pdo->prepare('INSERT INTO contact_messages(name,email,message) VALUES(?,?,?)');$s->execute([$name,$email,$message]);}catch(Throwable $e){}} flash('Your message has been received.');header('Location:contact.php');exit;}} page_top('Contact');?><section class="auth-card"><h1>Contact Student Hub</h1><?php foreach($errors as $error):?><p class="flash error"><?=e($error)?></p><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Name<input required name="name"></label><label>Email<input required type="email" name="email"></label><label>Message<textarea required minlength="10" name="message" rows="6"></textarea></label><button>Send message</button></form><p><a href="index.php">Sign in</a></p></section><?php page_bottom();
